(function(){'use strict';const{n}=PlatformUI,M=NeuroModel,pct=x=>x===null?'не определено':new Intl.NumberFormat('ru-RU',{style:'percent',maximumFractionDigits:1}).format(x),num=x=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(x);
 function slider(box,title,value,change){const l=n('label',undefined,'neuro-control'),input=n('input'),out=n('output',value+'%','neuro-value');input.type='range';input.setAttribute('aria-label',title);input.min=0;input.max=100;input.step=1;input.value=value;input.oninput=()=>{out.textContent=input.value+'%';change(Number(input.value)/100);};l.append(n('span',title),input,out);box.append(l);return{input,set(v){input.value=v;out.textContent=v+'%';}};}
 function setup(id,title,goal,source,block){const panel=document.getElementById('p-'+id);panel.append(n('h2',title),n('p',goal,'sub'),n('p','Вымышленные числовые данные. Модель объясняет интерпретацию, не оценивает конкретного пациента или препарат.','platform-note'));const grid=n('div',undefined,'neuro-experiment'),view=n('div',undefined,'neuro-view'),controls=n('div',undefined,'neuro-controls');grid.append(view,controls);panel.append(grid);const sources=n('p',undefined,'module-source'),a=n('a','Oxford 8 · исходный раздел');a.href='index.html#section='+source+'&block='+block;sources.append(document.createTextNode('Редакция 1 · '),a,document.createTextNode(' · Независимая клиническая редактура ожидается.'));panel.append(sources);const quiz=n('a','Проверить понимание →');quiz.href='quiz.html?collection=evidence';panel.append(quiz);return{view,controls};}
 function table(box,headers,rows){const t=n('table',undefined,'evidence-matrix'),head=n('thead'),tr=n('tr');headers.forEach(x=>tr.append(n('th',x)));head.append(tr);const body=n('tbody');for(const cells of rows){const r=n('tr');cells.forEach((x,i)=>{const c=n(i?'td':'th',x);if(!i)c.scope='row';r.append(c);});body.append(r);}t.append(head,body);box.replaceChildren(t);}
 {const{view,controls}=setup('bayes','Диагностический тест и базовая частота','Измените распространённость при неизменных чувствительности и специфичности. Какая доля положительных результатов относится к людям с состоянием?','ch06-s06',9);let prevalence=.1,sensitivity=.9,specificity=.8;const matrix=n('div'),result=n('div',undefined,'neuro-readout');view.append(matrix,result);slider(controls,'Распространённость',10,v=>{prevalence=v;draw();});slider(controls,'Чувствительность',90,v=>{sensitivity=v;draw();});slider(controls,'Специфичность',80,v=>{specificity=v;draw();});controls.append(n('p','Чувствительность: TP/(TP+FN). Специфичность: TN/(TN+FP). Положительная прогностическая ценность: TP/(TP+FP). В модели 10 000 человек.','fine'));function draw(){const r=M.diagnostic(prevalence,sensitivity,specificity);table(matrix,['Результат','Состояние есть','Состояния нет'],[['Тест +',num(r.tp)+' истинных +',num(r.fp)+' ложных +'],['Тест −',num(r.fn)+' ложных −',num(r.tn)+' истинных −']]);result.replaceChildren(n('strong','PPV: '+pct(r.ppv)),n('p','NPV: '+pct(r.npv)),n('p',r.ppv===null?'Положительных результатов нет, поэтому их прогностическая ценность не определена.':'Знаменатель PPV — все положительные результаты, а не все люди с состоянием. Результат теста не тождествен клиническому диагнозу.'));result.id='bayesResult';result.dataset.ppv=String(r.ppv);}draw();}
 {const{view,controls}=setup('effect','Абсолютный и относительный эффект','Сопоставьте частоты одного и того же неблагоприятного исхода за одинаковый вымышленный срок наблюдения.','ch06-s02',14);let control=.2,treated=.1;const result=n('div',undefined,'neuro-readout');view.append(result);slider(controls,'Риск в группе сравнения',20,v=>{control=v;draw();});slider(controls,'Риск в группе вмешательства',10,v=>{treated=v;draw();});controls.append(n('p','ARR = CER−EER; RR = EER/CER; RRR = ARR/CER. NNT = 1/ARR для снижения риска, NNH = 1/увеличение риска. Целое число округляется вверх.','fine'));function draw(){const r=M.effect(control,treated),label=r.arr>0?'Абсолютное снижение':r.arr<0?'Абсолютное увеличение':'Разность';result.replaceChildren(n('strong',label+': '+num(Math.abs(r.arr)*100)+' процентных пунктов'),n('p','RR: '+(r.rr===null?'не определён при CER=0':num(r.rr))),n('p','Относительное снижение риска: '+pct(r.rrr)),n('p',r.nnt?'NNT = '+r.nnt:r.nnh?'NNH = '+r.nnh:'Нет разности рисков: конечного NNT/NNH нет.'),n('p','Это точечные оценки. Доверительный интервал и срок наблюдения важны; цифры не являются основанием для назначения.'));result.id='effectResult';result.dataset.nnt=String(r.nnt);result.dataset.nnh=String(r.nnh);}draw();}
 {const{view,controls}=setup('confounding','Смешивающие факторы и переворот сравнения','В условном наблюдательном наборе по 1000 человек в каждой группе. Вмешательство чаще получают люди с более высоким исходным риском.','ch06-s07',1);let treated=.8,control=.2;const matrix=n('div'),result=n('div',undefined,'neuro-readout');view.append(matrix,result);const a=slider(controls,'Высокий риск: группа вмешательства',80,v=>{treated=v;draw();}),b=slider(controls,'Высокий риск: группа сравнения',20,v=>{control=v;draw();});for(const [title,x,y]of[['Смешанные группы',80,20],['Сопоставимые группы',50,50]]){const btn=n('button',title,'quiet outlined');btn.type='button';btn.onclick=()=>{treated=x/100;control=y/100;a.set(x);b.set(y);draw();};controls.append(btn);}controls.append(n('p','Условные риски фиксированы: низкий риск — 8% против 10%, высокий — 40% против 50%. Меняется состав групп, а не эффект в слоях. Учитывание одного фактора ещё не доказывает причинность.','fine'));function draw(){const r=M.confounding(treated,control);table(matrix,['Сравнение','Вмешательство','Контроль'],[['Низкий исходный риск','8%','10%'],['Высокий исходный риск','40%','50%'],['Вся группа',pct(r.treated),pct(r.control)],['Общий состав 50/50','24%','30%']]);result.replaceChildren(n('strong',r.treated>r.control?'Общее сравнение перевернулось':'В общем и послойном сравнении одно направление'),n('p',r.treated>r.control?'Внутри каждого слоя риск ниже при вмешательстве, но во всей группе — выше из-за различий состава. Нельзя выводить вред из одного сырого сравнения.':'При одинаковом составе виден другой общий результат. Иные неучтённые различия всё ещё могут влиять на причинную интерпретацию.'));result.id='confoundingResult';result.dataset.reversal=String(r.treated>r.control);}draw();}
})();
